from typing import Any, Literal
from typing_extensions import Annotated
from pydantic import BaseModel, Tag, Discriminator
from fastapi import FastAPI
from fastapi.testclient import TestClient
class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int
class ApplePie(Pie):
    fruit: Literal['apple'] = 'apple'
class PumpkinPie(Pie):
    filling: Literal['pumpkin'] = 'pumpkin'
def get_discriminator_value(v: Any) -> str:
    if isinstance(v, dict):
        return v.get('fruit', v.get('filling'))
    return getattr(v, 'fruit', getattr(v, 'filling', None))
Dessert = Annotated[Annotated[ApplePie, Tag('apple')] | Annotated[PumpkinPie, Tag('pumpkin')], Discriminator(get_discriminator_value)]
app = FastAPI()
@app.post('/dessert')
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()
c = TestClient(app)
r = c.post('/dessert', json={'time_to_cook':1,'num_ingredients':2,'fruit':'apple'})
print(r.status_code, r.json())
print(c.get('/openapi.json').status_code)
